from __future__ import annotations
import html,json
from pathlib import Path
def generate_html(root:Path)->Path:
 out=root/"data/processed/xai_final_reports/DockForgeAI_XAI_Benchmark_Report.html";out.parent.mkdir(parents=True,exist_ok=True);best=json.loads((root/"data/processed/xai_benchmarks/best_model.json").read_text());sections=["Executive summary","Dataset design","Active and decoy definitions","Scaffold-safe splitting","Feature engineering","Models","Hyperparameter selection","Validation strategy","Test performance","Calibration","Applicability domain","Global explanations","Fingerprint interpretation","Local explanations","Explanation stability","Ablation studies","Random vs scaffold split comparison","Statistical comparison","Limitations","Reproducibility","Conclusion"]
 body="".join(f"<section><h2>{s}</h2><p>See machine-readable benchmark artifacts and manifests for details.</p></section>" for s in sections);out.write_text(f"<!doctype html><html><head><meta charset='utf-8'><title>DockForgeAI XAI Benchmark</title><style>body{{max-width:1000px;margin:auto;font:16px system-ui}}section{{padding:1rem;border-bottom:1px solid #ddd}}</style></head><body><h1>DockForgeAI XAI Benchmark Report</h1><p>Best selected model: {html.escape(best['model_id'])}</p><p><strong>DUD-E decoys are not experimentally verified inactive molecules. SHAP and feature importance explain model behaviour, not biological causality. Good classification does not prove binding or therapeutic activity.</strong></p>{body}</body></html>");return out
